Perturbación 2: desplaza setups existentes a un período adyacente, adelantando o retrasando lotes sin cambiar el número de setups del ítem.
```python
from random import Random

from generated.clsp_setups_opusmodel.model.parts import canonical

COMPONENT = {
    "name": "adjacent_setup_shift",
    "slot": "perturbation",
    "compatible_skeletons": ["ILS"],
    "requires": [],
    "params": {"merge_prob": {"type": "float", "range": [0.0, 0.5]}},
}


class AdjacentSetupShift:
    def __init__(self, problem, merge_prob=0.2):
        self.problem = problem
        self.n = problem.inst.n_items
        self.T = problem.inst.n_periods
        self.merge_prob = float(merge_prob)

    def perturb(self, sol, strength: float, rng: Random):
        n, T = self.n, self.T
        base = canonical(sol)
        if n * T == 0:
            return base
        plan = [list(r) for r in base]
        k = max(1, int(round(strength)))
        for _ in range(k):
            on_cells = [(i, t) for i in range(n) for t in range(T) if plan[i][t]]
            if not on_cells or T < 2:
                i, t = rng.randrange(n), rng.randrange(T)
                plan[i][t] = not plan[i][t]
                continue
            i, t = rng.choice(on_cells)
            dirs = [dt for dt in (-1, 1) if 0 <= t + dt < T]
            dt = rng.choice(dirs)
            u = t + dt
            if plan[i][u]:
                # el vecino ya tiene setup: fusionar lotes (eliminar este) con cierta probabilidad
                if rng.random() < self.merge_prob or len(dirs) == 1:
                    plan[i][t] = False
                else:
                    other = t - dt
                    if 0 <= other < T and not plan[i][other]:
                        plan[i][t] = False
                        plan[i][other] = True
                    else:
                        plan[i][t] = False
            else:
                plan[i][t] = False
                plan[i][u] = True
        out = canonical(plan)
        if out == base:
            i, t = rng.randrange(n), rng.randrange(T)
            plan[i][t] = not plan[i][t]
            out = canonical(plan)
        return out


def build_component(problem, merge_prob=0.2):
    return AdjacentSetupShift(problem, merge_prob=merge_prob)
```

Perturbación 3: reconstruye por completo las filas de algunos ítems con un patrón periódico aleatorio (POQ) y repara la factibilidad añadiendo setups.
```python
from random import Random

from generated.clsp_setups_opusmodel.model.parts import canonical

COMPONENT = {
    "name": "item_row_periodic_rebuild",
    "slot": "perturbation",
    "compatible_skeletons": ["ILS"],
    "requires": [],
    "params": {
        "max_period": {"type": "int", "range": [1, 8]},
        "repair": {"type": "bool"},
    },
}


class ItemRowPeriodicRebuild:
    def __init__(self, problem, max_period=4, repair=True):
        self.problem = problem
        inst = problem.inst
        self.n = inst.n_items
        self.T = inst.n_periods
        self.demand = inst.demand
        self.max_period = max(1, int(max_period))
        self.repair = bool(repair)

    def _row(self, i, rng):
        T = self.T
        first = next((t for t in range(T) if self.demand[i][t] > 1e-9), None)
        row = [False] * T
        if first is None:
            return row
        p = rng.randint(1, max(1, min(self.max_period, T)))
        t = first
        while t < T:
            row[t] = True
            t += p
        return row

    def perturb(self, sol, strength: float, rng: Random):
        n, T = self.n, self.T
        base = canonical(sol)
        if n * T == 0:
            return base
        k = max(1, min(n, int(round(strength))))
        items = rng.sample(range(n), k)
        plan = [list(r) for r in base]
        for i in items:
            plan[i] = self._row(i, rng)
        if self.repair:
            tries = k * T
            while tries > 0 and not self.problem.is_feasible(canonical(plan)):
                tries -= 1
                cand = [(i, t) for i in items for t in range(T)
                        if not plan[i][t] and self.demand[i][t] > 1e-9]
                if not cand:
                    break
                i, t = rng.choice(cand)
                plan[i][t] = True
        out = canonical(plan)
        if out == base:
            i = rng.choice(items)
            t = rng.randrange(T)
            plan[i][t] = not plan[i][t]
            out = canonical(plan)
        return out


def build_component(problem, max_period=4, repair=True):
    return ItemRowPeriodicRebuild(problem, max_period=max_period, repair=repair)
